mapper.select:
SELECT id, snap_date, investor_type, trade_type, market, rank,
       stock_code, stock_name, net_buy_amount, net_buy_volume
FROM ranking_snapshot
WHERE snap_date    = #{snapDate}
  AND investor_type = #{investorType}
  AND trade_type    = #{tradeType}
  AND market        = #{market}
ORDER BY rank

SELECT DISTINCT TO_CHAR(snap_date, 'YYYYMMDD')
FROM ranking_snapshot
WHERE investor_type = #{investorType}
  AND trade_type    = #{tradeType}
  AND market        = #{market}
ORDER BY 1 DESC

SELECT id, snap_date, investor_type, trade_type, market, rank,
       stock_code, stock_name, net_buy_amount, net_buy_volume
FROM ranking_snapshot
WHERE investor_type = #{investorType}
  AND trade_type    = #{tradeType}
  AND market        = #{market}
  AND snap_date = (
      SELECT MAX(snap_date) FROM ranking_snapshot
      WHERE investor_type = #{investorType}
        AND trade_type    = #{tradeType}
        AND market        = #{market}
  )
ORDER BY rank
